    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    motif = [v for v in grid[-1] if v != bg]
    marker = next(v for v in set(v for row in grid[:-1] for v in row if v != bg) if v not in motif and v != 0)
    anchor = len(motif) // 2
    out = [row[:] for row in grid]
    for r in range(h - 1):
        for c, v in enumerate(grid[r]):
            if v == marker:
                for k, color in enumerate(motif):
                    j = c + k - anchor
                    if 0 <= j < w:
                        out[r][j] = color
    return out

